<script setup lang="ts">
import { Upload, Search, Check, ImagePlus } from 'lucide-vue-next'
import type { Asset } from '@qinbian/shared'
const emit=defineEmits<{close:[];select:[asset:Asset]}>(),ctx=useQinbian(),items=ref<Asset[]>([]),query=ref(''),uploading=ref(false),fileInput=ref<HTMLInputElement>()
const filtered=computed(()=>items.value.filter(a=>a.name.toLowerCase().includes(query.value.toLowerCase())))
async function refresh(){items.value=await apiFetch('/api/assets')};onMounted(()=>refresh().catch(ctx.error))
async function upload(files:FileList|null){if(!files)return;uploading.value=true;try{for(const f of Array.from(files)){const body=new FormData();body.append('file',f);const item=await apiFetch<Asset>('/api/assets',{method:'POST',body});items.value=[item,...items.value.filter(a=>a.id!==item.id)]}ctx.notify('图片已存入素材库')}catch(e){ctx.error(e)}finally{uploading.value=false;if(fileInput.value)fileInput.value.value=''}}
</script>
<template><UiModal title="从素材库选图" subtitle="原图保存在本机，可在不同文章中重复使用。" wide @close="emit('close')"><div class="picker-toolbar"><label class="search-field"><Search :size="16"/><input v-model="query" placeholder="搜索图片名称" aria-label="搜索素材"></label><button class="btn" :disabled="uploading" @click="fileInput?.click()"><Upload :size="15"/>{{uploading?'正在上传…':'上传图片'}}</button><input ref="fileInput" type="file" hidden multiple accept="image/jpeg,image/png,image/webp,image/gif" @change="upload(($event.target as HTMLInputElement).files)"></div><div class="asset-picker-grid"><button v-for="a in filtered" :key="a.id" class="asset-pick" @click="emit('select',a)"><img :src="`/api/assets/${a.id}/thumbnail`" :alt="a.name"><span>{{a.name}}</span><small>{{a.width}} × {{a.height}}</small></button></div><div v-if="!filtered.length" class="empty-state"><ImagePlus :size="32"/><h3>先收进一张图片</h3><p>支持 JPG、PNG、WebP 与 GIF，单张不超过20 MB。</p></div></UiModal></template>
